// Records exchanged with the Rust side. The JSON the bundled Afterhours.exe
// prints (`status --json`, `check --json`) is generated from schemas/ into
// ./generated by `pnpm types`; the rest mirrors src-tauri/src.

export type { State as SessionState, Status, StatusReport } from "./generated/status";
export type { Preflight } from "./generated/check";

export type CliResult =
  { kind: "ok"; value: unknown } | { kind: "error"; exit: number; message: string };

export type UpdateMode = "ask" | "auto" | "off";

export interface UpdateSettings {
  mode: UpdateMode;
  skipped_version: string | null;
}

export interface Settings {
  game_dir: string | null;
  data_dir: string | null;
  player_name: string | null;
  avatar: string | null;
  first_run_done: boolean;
  updates: UpdateSettings;
  last_server_tag: string | null;
}

export type OutputLine =
  { kind: "status"; time: string; state: string; message: string } | { kind: "text"; text: string };

export type SessionAction = "setup" | "serve" | "start";

/** `status --json` as the server answered it. */
export type StatusProbe = { kind: "ok"; state: string } | { kind: "error"; message: string };

/** The current session as the data directory's records describe it. */
export type Recorded =
  | { kind: "none" }
  | {
      kind: "session";
      id: string;
      state: string;
      message: string;
      utc: string;
      /** Probed only for a live state; null when it could not be. */
      lock_held: boolean | null;
    }
  | { kind: "error"; message: string };

export interface Activity {
  cli: StatusProbe;
  recorded: Recorded;
  window_session: boolean;
}

export interface BackedUpFile {
  path: string;
  bytes: number;
  sha256: string;
}

export interface BackupReport {
  folder: string | null;
  files: BackedUpFile[];
}

export interface ServerInfo {
  repository: string;
  pinned_tag: string;
  pinned_sha256: string;
  override_allowed: boolean;
  path: string | null;
  source: "bundled" | "override" | null;
  version_line: string | null;
  matches_pin: boolean | null;
  error: string | null;
}

export interface AppInfo {
  launcher_version: string;
  server: ServerInfo;
  data_dir: string | null;
  updater: { endpoint: string | null; configured: boolean };
  debug_build: boolean;
}

export type Folder = "data" | "session" | "backups";

export function emptySettings(): Settings {
  return {
    game_dir: null,
    data_dir: null,
    player_name: null,
    avatar: null,
    first_run_done: false,
    updates: { mode: "ask", skipped_version: null },
    last_server_tag: null,
  };
}
